/* Builds data/bundle.js - every data file in ONE script, so the bot works even when it is opened from file://
   or when the JSON requests fail. Run after editing any data/*.json:   node tools/bundle.js */
var fs = require('fs'), path = require('path');
var D = path.join(__dirname, '..', 'data'), out = {};
['kb', 'people', 'kn', 'synonyms', 'forms', 'news', 'rates', 'jobs', 'products'].forEach(function (n) {
  out[n] = JSON.parse(fs.readFileSync(path.join(D, n + '.json'), 'utf8'));
  delete out[n]._readme;
});
fs.writeFileSync(path.join(D, 'bundle.js'), '/* generated by tools/bundle.js - do not edit */\nwindow.CampcoBotData=' + JSON.stringify(out) + ';\n');
console.log('bundle.js written,', fs.statSync(path.join(D, 'bundle.js')).size, 'bytes');
